mapper.update:
UPDATE biz_delivery_report_google_template
SET deleted_at = #{deletedAt}, updated_by = #{updatedBy}
WHERE id = #{id} AND deleted_at = 0

mapper.insert:
INSERT INTO biz_delivery_report_google_push_batch (
    status, total_count, success_count, failed_count, requested_by
) VALUES (0, #{totalCount}, 0, 0, #{requestedBy})

mapper.select:
SELECT id, status, total_count, success_count, failed_count, requested_by,
    error_message, started_at, finished_at, created_at
FROM biz_delivery_report_google_push_batch
WHERE requested_by = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
